@@ -0,0 +1,155 @@
+(function() {
+  'use strict';
+
+  const STORAGE_KEY = 'validated_form_data_v1';
+  const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+  const PHONE_PATTERN = /^[\d\s\-\+\(\)]{10,}$/;
+
+  function normalizeEmail(email) {
+    if (!EMAIL_PATTERN.test(email)) return null;
+    return email.toLowerCase().trim();
+  }
+
+  function normalizePhone(phone) {
+    if (!PHONE_PATTERN.test(phone)) return null;
+    return phone.replace(/\D/g, '');
+  }
+
+  function loadState() {
+    try {
+      const data = localStorage.getItem(STORAGE_KEY);
+      return data ? JSON.parse(data) : null;
+    } catch (e) {
+      console.error('Failed to load state:', e);
+      return null;
+    }
+  }
+
+  function saveState(data) {
+    try {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
+      return true;
+    } catch (e) {
+      console.error('Failed to save state:', e);
+      return false;
+    }
+  }
+
+  function validateForm() {
+    const emailInput = document.getElementById('email');
+    const phoneInput = document.getElementById('phone');
+    const nameInput = document.getElementById('name');
+
+    if (!nameInput.value.trim()) {
+      showError(nameInput, 'Name is required');
+      return false;
+    }
+
+    const normalizedEmail = normalizeEmail(emailInput.value);
+    if (!normalizedEmail) {
+      showError(emailInput, 'Please enter a valid email address');
+      return false;
+    }
+
+    const normalizedPhone = normalizePhone(phoneInput.value);
+    if (!normalizedPhone) {
+      showError(phoneInput, 'Please enter a valid phone number');
+      return false;
+    }
+
+    const state = {
+      name: nameInput.value.trim(),
+      email: normalizedEmail,
+      phone: normalizedPhone,
+      timestamp: new Date().toISOString()
+    };
+
+    if (saveState(state)) {
+      showSuccess('Form validated and saved successfully!');
+      return true;
+    } else {
+      showError(null, 'Failed to save data. Please try again.');
+      return false;
+    }
+  }
+
+  function showError(element, message) {
+    if (element) {
+      element.classList.add('error');
+      const existingMsg = element.querySelector('.error-message');
+      if (existingMsg) existingMsg.textContent = message;
+      else {
+        const msg = document.createElement('span');
+        msg.className = 'error-message';
+        msg.textContent = message;
+        element.parentNode.insertBefore(msg, element.nextSibling);
+      }
+    } else {
+      alert(message);
+    }
+  }
+
+  function showSuccess(message) {
+    const existingMsg = document.querySelector('.success-message');
+    if (existingMsg) existingMsg.textContent = message;
+    else {
+      const msg = document.createElement('div');
+      msg.className = 'success-message';
+      msg.textContent = message;
+      document.body.appendChild(msg);
+    }
+  }
+
+  function init() {
+    const emailInput = document.getElementById('email');
+    const phoneInput = document.getElementById('phone');
+    const nameInput = document.getElementById('name');
+
+    if (emailInput) {
+      emailInput.addEventListener('input', () => {
+        const normalized = normalizeEmail(emailInput.value);
+        if (normalized) emailInput.value = normalized;
+      });
+    }
+
+    if (phoneInput) {
+      phoneInput.addEventListener('input', () => {
+        const normalized = normalizePhone(phoneInput.value);
+        if (normalized) phoneInput.value = normalized;
+      });
+    }
+
+    const submitBtn = document.getElementById('submit');
+    if (submitBtn) {
+      submitBtn.addEventListener('click', validateForm);
+    }
+
+    const resetBtn = document.getElementById('reset');
+    if (resetBtn) {
+      resetBtn.addEventListener('click', () => {
+        localStorage.removeItem(STORAGE_KEY);
+        emailInput.value = '';
+        phoneInput.value = '';
+        nameInput.value = '';
+        showSuccess('Form cleared and state removed.');
+      });
+    }
+
+    const loadStateBtn = document.getElementById('load');
+    if (loadStateBtn) {
+      loadStateBtn.addEventListener('click', () => {
+        const state = loadState();
+        if (state) {
+          emailInput.value = state.email;
+          phoneInput.value = state.phone;
+          nameInput.value = state.name;
+          showSuccess('Previous data loaded successfully!');
+        } else {
+          alert('No saved data found.');
+        }
+      });
+    }
+  }
+
+  document.addEventListener('DOMContentLoaded', init);
+})();

